r:[
{t:"Дата в таблиці — це число",v:["flow", ["1 січня 1900 (або 1899) = 1", "Кожен день +1", "Дата = номер дня", "Формат показує календарну дату"]],
 p:"Програма зберігає дату як <b>порядковий номер дня</b> від початкової дати відліку. Тому дати можна додавати, віднімати й порівнювати. Формат комірки визначає, як це число показується: <code>15.11.2026</code> чи «15 листопада 2026». Якщо замість дати бачиш число — змінись формат на «Дата».",
 k:["Дата — число з форматом", "Різниця дат — кількість днів", "Формат змінює вигляд, не значення", "Час — дробова частина доби"],
 f:"Час 12:00 — це 0,5 доби, а 18:00 — 0,75.",fl:"Цікаво"},
{t:"Поточна дата і час",v:["tiles", [["📅", "TODAY() — сьогодні"], ["⏰", "NOW() — зараз"], ["🧮", "DATE(рік; місяць; день)"], ["🕒", "TIME(год; хв; с)"]]],
 p:"<code>TODAY()</code> повертає поточну дату, <code>NOW()</code> — дату й час; обидві оновлюються при кожному перерахунку. <code>DATE(2026;11;15)</code> створює дату з трьох чисел. Назви функцій наведено англійською; в українській версії програми вони можуть відрізнятися (наприклад, SUM — СУМ, IF — ЯКЩО), а роздільником аргументів зазвичай є «;» замість «,».",
 k:["TODAY — лише дата", "NOW — дата та час", "DATE складає дату з частин", "Оновлюються автоматично"],
 f:"Українською: СЬОГОДНІ() та ЗАРАЗ().",fl:"Важливо"},
{t:"YEAR, MONTH, DAY, WEEKDAY",v:["tiles", [["Y", "YEAR(дата)"], ["M", "MONTH(дата)"], ["D", "DAY(дата)"], ["📆", "WEEKDAY(дата; тип)"]]],
 p:"Ці функції «розбирають» дату: <code>YEAR</code> — рік, <code>MONTH</code> — місяць (1–12), <code>DAY</code> — число, <code>WEEKDAY</code> — день тижня. Другий аргумент WEEKDAY задає нумерацію: <code>WEEKDAY(A1;2)</code> дає 1 для понеділка й 7 для неділі.",
 k:["Рік, місяць, день", "WEEKDAY(…;2): понеділок = 1", "Корисно для звітів за період", "Групування за місяцями"],
 f:"Місяць у вигляді назви можна отримати форматом комірки або функцією TEXT.",fl:"Практика"},
{t:"Обчислення з датами",v:["vs", ["Різниця", ["=B1-A1", "Кількість днів"]], ["Додавання", ["=A1+30", "Дата через 30 днів"]]],
 p:"Різниця двох дат — кількість днів між ними: <code>=B1-A1</code> (комірку-результат форматуй як «Число»). Додавання числа зсуває дату вперед: <code>=A1+30</code>. Для місяців є <code>EDATE(дата;кількість_місяців)</code>, а <code>DATEDIF(початок;кінець;\"Y\")</code> рахує повні роки (корисно для віку).",
 k:["Віднімання дат → дні", "Додавання днів до дати", "EDATE — місяці", "DATEDIF — повні роки"],
 f:"DATEDIF працює, але в частині програм не показується в підказках.",fl:"Лайфхак"},
{t:"Час у таблиці",v:["flow", ["Час — частка доби", "18:00 = 0,75", "Різниця часу", "Формат [г]:хх"]],
 p:"Час зберігається як дробова частина доби: 6:00 = 0,25. Різницю часів знаходять відніманням <code>=B1-A1</code> з форматом часу. Щоб показувати понад 24 години, застосовують формат <code>[г]:хх</code> (в англійській версії <code>[h]:mm</code>). Помилка «#####» може означати від’ємний час.",
 k:["Час — дробове число", "Різниця = віднімання", "Формат для підсумків > 24 год", "#### — завузький стовпець або від’ємний час"],
 f:"Підсумок годин за тиждень не дорівнює «сума за модулем 24».",fl:"Пастка"},
{t:"Практичні задачі",v:["flow", ["Скільки днів до канікул", "Скільки повних років", "Дата завершення проєкту", "День тижня"]],
 p:"Приклади: <code>=DATE(2026;12;25)-TODAY()</code> — скільки днів до події; <code>=DATEDIF(A2;TODAY();\"Y\")</code> — вік у повних роках; <code>=WORKDAY(A2;10)</code> — дата через 10 робочих днів. Дати зручно сортувати й фільтрувати — вони числа.",
 k:["Відлік днів до події", "Вік за датою народження", "WORKDAY — робочі дні", "Дати можна фільтрувати за місяцями"],
 f:"Підписуй стовпці з датами — формат може вводити в оману.",fl:"Практика"}
],
