r:[
{t:"Навіщо функції пошуку",v:["flow", ["Є ключ (код, ім’я)", "Шукаємо в таблиці", "Отримуємо потрібне значення"]],
 p:"Дані часто лежать у кількох таблицях: в одній — коди товарів і ціни, в іншій — що купив клієнт. <b>Функції пошуку</b> дозволяють за ключем (кодом, прізвищем) підтягнути з іншої таблиці потрібне значення. Це заміна ручному «знайди й скопіюй».",
 k:["Ключ пошуку", "Таблиця-довідник", "Значення з потрібного стовпця", "Автоматичне підтягування даних"],
 f:"Так працюють зведення цін, відомостей, оцінок.",fl:"Важливо"},
{t:"VLOOKUP (ВПР)",v:["flow", ["Що шукаю", "Де шукаю", "Номер стовпця", "Точний збіг"]],
 p:"<code>VLOOKUP(що_шукати; таблиця; номер_стовпця; режим)</code> шукає значення в <b>першому стовпці</b> таблиці й повертає значення з вказаного стовпця. Режим <code>FALSE</code> (або 0) — точний збіг. Приклад: <code>=VLOOKUP(A2;$E$2:$G$50;3;FALSE)</code>. Таблицю фіксуй абсолютним посиланням. Назви функцій наведено англійською; в українській версії програми вони можуть відрізнятися (наприклад, SUM — СУМ, IF — ЯКЩО), а роздільником аргументів зазвичай є «;» замість «,».",
 k:["Ключ має бути в першому стовпці довідника", "3 — номер стовпця від початку таблиці", "FALSE — точний збіг", "Українською: ВПР"],
 f:"Без четвертого аргументу VLOOKUP шукає найближче, і результат може бути хибним.",fl:"Увага"},
{t:"Помилка #N/A та IFERROR",v:["tiles", [["🚫", "#N/A — значення не знайдено"], ["🛡️", "IFERROR(формула; запасне)"]]],
 p:"<code>#N/A</code> означає, що ключа немає в довіднику (можлива помилка в написанні чи зайві пробіли). Щоб замінити помилку зрозумілим повідомленням, використовують <code>IFERROR(VLOOKUP(…);\"не знайдено\")</code>. Але не ховай помилки без потреби: вони допомагають виявити проблеми.",
 k:["#N/A — не знайдено", "IFERROR — запасне значення", "Перевір пробіли й регістр", "Не маскуй усі помилки підряд"],
 f:"Шукаєш «Іваненко», а в довіднику «Іваненко » — з пробілом: це різні ключі.",fl:"Пастка"},
{t:"INDEX і MATCH",v:["flow", ["MATCH знаходить номер рядка", "INDEX повертає значення з цього рядка"]],
 p:"<code>MATCH(що; діапазон; 0)</code> повертає <b>позицію</b> знайденого значення, <code>INDEX(діапазон; номер)</code> — значення за номером. Разом: <code>=INDEX(C2:C50;MATCH(A2;B2:B50;0))</code>. Ця пара гнучкіша за VLOOKUP: ключ може бути в будь-якому стовпці, а додавання стовпців не ламає формулу.",
 k:["MATCH — позиція", "INDEX — значення за позицією", "Ключ — не обов’язково перший стовпець", "Стійка до додавання стовпців"],
 f:"MATCH(…;0) — точний збіг; не забувай третій аргумент.",fl:"Просунуте"},
{t:"XLOOKUP",v:["tiles", [["🔭", "Шукає в будь-якому напрямку"], ["🧰", "Вбудований запас при невдачі"], ["🎯", "Точний збіг за замовчуванням"]]],
 p:"<code>XLOOKUP(що; де_шукати; що_повернути; [якщо_не_знайдено])</code> — новіша функція (є в сучасних Excel та Google Таблицях). Вона простіша за VLOOKUP: не потрібен номер стовпця, ключ може бути де завгодно, а запасне значення задається четвертим аргументом. Приклад: <code>=XLOOKUP(A2;E:E;G:G;\"немає\")</code>.",
 k:["Не потрібен номер стовпця", "Ключ у будь-якому стовпці", "Запасне значення вбудоване", "Є не у всіх програмах"],
 f:"Якщо XLOOKUP недоступна, користуйся INDEX+MATCH.",fl:"Лайфхак"},
{t:"HLOOKUP та практичний приклад",v:["flow", ["Код → довідник", "VLOOKUP / XLOOKUP", "Назва, ціна, категорія", "Звіт"]],
 p:"<code>HLOOKUP</code> — «горизонтальний» аналог VLOOKUP: шукає у першому <i>рядку</i> й повертає значення з нижчого рядка. У типовій задачі в журналі продажів є код товару; за ним VLOOKUP підтягує назву й ціну з довідника. Далі формулою рахуємо суму: кількість × ціна.",
 k:["HLOOKUP — у рядку", "Код → назва, ціна", "Далі — розрахунки", "Довідник краще оформити окремим аркушем"],
 f:"Один довідник — єдине джерело правди для багатьох звітів.",fl:"Практика"}
],
