r:[
{t:"Масиви",v:JS("const a = [10, 20, 30];\nconsole.log(a[0], a.length);\na.push(40);\nconsole.log(a);\nconsole.log(a.pop(), a);\nconsole.log(a.indexOf(20), a.includes(99));","10 3\n[ 10, 20, 30, 40 ]\n40 [ 10, 20, 30 ]\n1 false"),
 p:"<b>Масив</b> — впорядкований набір значень. Записують у квадратних дужках, елементи нумерують з нуля, довжина — властивість <code>length</code>. Додають <code>push</code> (в кінець), видаляють <code>pop</code> (з кінця). Масив може містити значення різних типів.",
 k:["[1, 2, 3] — масив", "Індекси з 0", "push / pop — кінець масиву", "length — довжина"],
 f:"Масиви в JavaScript схожі на списки в Python.",fl:"Важливо"},
{t:"Перебір масиву",v:JS("const nums = [1, 2, 3, 4, 5];\nfor (const x of nums) {\n  if (x % 2 === 0) console.log(\"парне\", x);\n}\nconsole.log(nums.map((x) => x * 10));\nconsole.log(nums.filter((x) => x > 2));\nconsole.log(nums.reduce((s, x) => s + x, 0));","парне 2\nпарне 4\n[ 10, 20, 30, 40, 50 ]\n[ 3, 4, 5 ]\n15"),
 p:"Масив перебирають циклом <code>for</code>, <code>for…of</code> або методом <code>forEach</code>. Методи <code>map</code> (перетворення), <code>filter</code> (відбір) повертають новий масив, а <code>reduce</code> зводить масив до одного значення. Вони приймають функцію як аргумент.",
 k:["for…of — перебір значень", "map — перетворює кожен елемент", "filter — залишає потрібні", "forEach — виконує дію для кожного"],
 f:"map і filter не змінюють початковий масив — вони створюють новий.",fl:"Практика"},
{t:"Об’єкти",v:JS("const user = { name: \"Оля\", age: 16 };\nconsole.log(user.name, user[\"age\"]);\nuser.city = \"Ладан\";\nuser.age = 17;\nconsole.log(user);\ndelete user.city;\nconsole.log(Object.keys(user));","Оля 16\n{ name: 'Оля', age: 17, city: 'Ладан' }\n[ 'name', 'age' ]"),
 p:"<b>Об’єкт</b> — набір пар «ключ: значення» у фігурних дужках. Доступ до властивості: через крапку (<code>user.name</code>) або дужки (<code>user[\"name\"]</code>). Властивості можна додавати, змінювати, видаляти. Об’єкти схожі на словники в Python.",
 k:["{ ключ: значення }", "Доступ: obj.key", "Можна додавати й видаляти властивості", "Значенням може бути функція (метод)"],
 f:"Імена властивостей без пробілів записуй без лапок.",fl:"Важливо"},
{t:"Масив об’єктів",v:JS("const students = [\n  { name: \"Оля\", mark: 11 },\n  { name: \"Ден\", mark: 8 },\n  { name: \"Іра\", mark: 12 }\n];\nconsole.log(students.find((s) => s.name === \"Ден\"));\nconsole.log(students.filter((s) => s.mark >= 10).map((s) => s.name));\nconsole.log(students.sort((a, b) => b.mark - a.mark)[0].name);","{ name: 'Ден', mark: 8 }\n[ 'Оля', 'Іра' ]\nІра"),
 p:"Типова структура даних для вебу — масив об’єктів: кожен об’єкт описує один запис (учня, товар, завдання). Перебір, пошук і відбір відбуваються методами масиву: <code>find</code> шукає перший відповідний, <code>filter</code> відбирає всі, <code>sort</code> сортує.",
 k:["Масив записів", "find — перший збіг", "filter — усі збіги", "sort — сортування"],
 f:"Дані з сервера майже завжди приходять у вигляді масиву об’єктів (JSON).",fl:"Практика"},
{t:"Методи об’єктів і this",v:JS("const counter = {\n  value: 0,\n  inc() {\n    this.value++;\n    return this.value;\n  }\n};\ncounter.inc();\nconsole.log(counter.inc());","2"),
 p:"Властивістю об’єкта може бути функція — її називають <b>методом</b>. Усередині методу ключове слово <code>this</code> вказує на сам об’єкт. Стрілкові функції не мають власного <code>this</code>, тому як методи об’єкта їх використовувати не варто.",
 k:["Метод — функція всередині об’єкта", "this — сам об’єкт", "Виклик: obj.method()", "Не використовуй стрілкові функції як методи"],
 f:"Об’єкти з методами — основа об’єктно-орієнтованого програмування.",fl:"Просунуте"},
{t:"JSON: обмін даними",v:JS("const data = { name: \"Оля\", marks: [11, 12] };\nconst text = JSON.stringify(data);\nconsole.log(text);\nconst back = JSON.parse(text);\nconsole.log(back.marks[1]);","{\"name\":\"Оля\",\"marks\":[11,12]}\n12"),
 p:"Масиви та об’єкти легко перетворюються на текст у форматі JSON функцією <code>JSON.stringify</code> і назад — <code>JSON.parse</code>. Так дані передають між браузером і сервером або зберігають у <code>localStorage</code>. Ключі в JSON завжди беруть у подвійні лапки.",
 k:["JSON.stringify — об’єкт → текст", "JSON.parse — текст → об’єкт", "localStorage зберігає лише рядки", "Ключі в JSON у подвійних лапках"],
 f:"JSON схожий на об’єкти JavaScript, тому й отримав таку назву — JavaScript Object Notation.",fl:"Цікаво"}
],
