r:[
{t:"Практика: мінімум, максимум і позиції",v:PY("a = [5, 2, 8, 2, 9]\nbest = 0\nfor i in range(1, len(a)):\n    if a[i] < a[best]:\n        best = i\nprint(\"Мінімум:\", a[best], \"на позиції\", best)\nlast = -1\nfor i in range(len(a)):\n    if a[i] == 2:\n        last = i\nprint(\"Остання двійка:\", last)\nprint(sum(1 for v in a if 2 <= v <= 8))","Мінімум: 2 на позиції 1\nОстання двійка: 3\n4"),
 p:"У практичній роботі застосуємо пошук до типових задач: знайти позицію мінімуму, перший або останній елемент за умовою, кількість елементів у діапазоні. Для кожної задачі спершу сформулюй, який пошук потрібен: за значенням, за умовою чи найбільший/найменший.",
 k:["Позиція мінімуму: пам’ятай індекс", "Перший/останній за умовою: прохід зліва або справа", "Кількість у діапазоні: лічильник", "Тестуй на повтори й порожньому списку"],
 f:"Якщо мінімумів кілька, чітко вирішіть: беремо перший чи всі.",fl:"Практика"},
{t:"Практика: бінарний пошук за відповіддю",v:PY("def int_sqrt(n):\n    low, high = 0, n\n    while low <= high:\n        mid = (low + high) // 2\n        if mid * mid <= n:\n            ans = mid\n            low = mid + 1\n        else:\n            high = mid - 1\n    return ans\n\nprint(int_sqrt(50), int_sqrt(64), int_sqrt(2))","7 8 1"),
 p:"Бінарний пошук можна застосовувати не лише до списків, а й до числових відповідей: наприклад, знайти цілий корінь числа. Діапазон — від 0 до n, перевірка — квадрат середини. Умова: функція монотонна (зростає).",
 k:["Діапазон можливих відповідей", "Перевірка середини", "Звужуємо діапазон за результатом", "Підходить для монотонних функцій"],
 f:"Так шукають «найменше значення, яке задовольняє умову».",fl:"Просунуте"},
{t:"Практика: чек-лист",v:["tiles", [["📚", "Порядок даних"], ["🧪", "Тести"], ["🔢", "Лічильник"], ["🔁", "Тип результату"]]],
 p:"Перед здаванням перевір: чи дані впорядковані там, де це потрібно; чи є тести для першого, останнього й відсутнього елемента; чи лічильник порівнянь підтверджує очікувану складність; чи функція повертає однаковий тип результату.",
 k:["Порядок даних", "Тести на краях і відсутності", "Лічильник порівнянь", "Однаковий тип результату"],
 f:"Хороша практика — записати очікуваний результат до запуску коду.",fl:"Порада"}
],
